<?php require_once '../config/config.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) author FROM recipes r LEFT JOIN users u ON u.id=r.author_id WHERE r.id=? AND r.status='approved'");$s->execute([$id]);$r=$s->fetch();if(!$r){http_response_code(404);exit('Recipe not found');}$title=$r['title'];$cm=db()->prepare("SELECT c.*,CONCAT(u.first_name,' ',u.last_name) author FROM recipe_comments c JOIN users u ON u.id=c.user_id WHERE c.recipe_id=? ORDER BY c.created_at DESC");$cm->execute([$id]);$comments=$cm->fetchAll();require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow"><?=e($r['cuisine'])?></span><h1 class="fw-bold"><?=e($r['title'])?></h1><p class="lead"><?=e($r['description'])?></p></div></div><section class="section"><div class="container"><div class="row g-5"><div class="col-lg-6"><img class="img-fluid rounded-4 w-100" src="<?=recipe_image($r['image'])?>" alt="<?=e($r['title'])?>"></div><div class="col-lg-6"><span class="tag"><?=e($r['difficulty'])?></span><span class="tag ms-1"><?=e($r['dietary_preference'])?></span><div class="row g-3 my-4"><div class="col-4"><strong><?=$r['prep_time']?>m</strong><small class="d-block text-muted">Prep</small></div><div class="col-4"><strong><?=$r['cook_time']?>m</strong><small class="d-block text-muted">Cook</small></div><div class="col-4"><strong><?=$r['servings']?></strong><small class="d-block text-muted">Servings</small></div></div><?php if(user()):?><form method="post" action="../api/recipe-action.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="recipe_id" value="<?=$id?>"><input type="hidden" name="action" value="favourite"><button class="btn btn-outline-dark">♡ Save Recipe</button></form><?php endif;?></div></div><div class="row g-5 mt-4"><div class="col-lg-5"><h3>Ingredients</h3><p><?=nl2br(e($r['ingredients']))?></p><?php if($yt=youtube_id($r['video_url']??null)):?><div class="mt-4"><h3>Watch how to make it</h3><div class="ratio ratio-16x9 mt-2"><iframe src="https://www.youtube-nocookie.com/embed/<?=e($yt)?>" title="Video: <?=e($r['title'])?>" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div></div><?php endif;?></div><div class="col-lg-7"><h3>Instructions</h3><p><?=nl2br(e($r['instructions']))?></p><h3 class="mt-4">Cooking tips</h3><p><?=nl2br(e($r['cooking_tips']))?></p></div></div><div class="mt-5"><h3>Community comments</h3><?php if(user()):?><form method="post" action="../api/recipe-action.php" class="mb-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="recipe_id" value="<?=$id?>"><input type="hidden" name="action" value="comment"><textarea class="form-control mb-2" name="comment" rows="3" required placeholder="Share your thoughts..."></textarea><button class="btn btn-primary">Post comment</button></form><?php else:?><p><a href="../login.php">Log in</a> to comment.</p><?php endif;?><?php foreach($comments as $x):?><div class="border-bottom py-3"><strong><?=e($x['author'])?></strong><p class="mb-0"><?=e($x['comment'])?></p></div><?php endforeach;?></div></div></section><?php require '../includes/footer.php';?>